<?php require_once __DIR__.'/../includes/functions.php';require_role('student');$s=$pdo->prepare("SELECT title,material_type,file_path FROM study_materials m JOIN students st ON st.class_id=m.class_id WHERE st.user_id=?");$s->execute([$_SESSION['user']['id']]);$rows=$s->fetchAll();$pageTitle='Study Materials';$base='../';require __DIR__.'/../includes/header.php';?>
<div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>Study Materials</h1><div class="table-wrap"><table class="table"><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>